import{_ as i,c as e,o as t,a3 as s}from"./chunks/framework.CoV49S2T.js";const g=JSON.parse('{"title":"インストール","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/installation.md","filePath":"ja/guide/installation.md","lastUpdated":1786595765000}'),o={name:"ja/guide/installation.md"};function l(r,a,n,p,h,c){return t(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to &quot;インストール&quot;">​</a></h1><p>ClipboardxAI は macOS 向けに提供されています。</p><h2 id="ダウンロード方法" tabindex="-1">ダウンロード方法 <a class="header-anchor" href="#ダウンロード方法" aria-label="Permalink to &quot;ダウンロード方法&quot;">​</a></h2><h3 id="mac-app-store-推奨" tabindex="-1">Mac App Store（推奨） <a class="header-anchor" href="#mac-app-store-推奨" aria-label="Permalink to &quot;Mac App Store（推奨）&quot;">​</a></h3><ul><li><strong>ダウンロード</strong>: Mac App Store で <strong>ClipboardxAI</strong> を検索するか、<a href="/ja/">ホームページ</a>のリンクから開いてください。</li><li>Mac App Store 版は自動更新とシームレスな macOS 統合を提供します。</li></ul><blockquote><p>Mac App Store のリンクがまだ利用できない場合は、以下の GitHub Releases ビルドをお使いください。</p></blockquote><h3 id="github-releases-代替" tabindex="-1">GitHub Releases（代替） <a class="header-anchor" href="#github-releases-代替" aria-label="Permalink to &quot;GitHub Releases（代替）&quot;">​</a></h3><p>最新のビルドは <a href="https://github.com/clipboardxAI" target="_blank" rel="noreferrer">GitHub Releases</a> から直接ダウンロードできます。このバージョンは自動更新に対応していません。</p><h2 id="インストール手順" tabindex="-1">インストール手順 <a class="header-anchor" href="#インストール手順" aria-label="Permalink to &quot;インストール手順&quot;">​</a></h2><h3 id="mac-app-store" tabindex="-1">Mac App Store <a class="header-anchor" href="#mac-app-store" aria-label="Permalink to &quot;Mac App Store&quot;">​</a></h3><ol><li>上記のダウンロードリンクを開くか、Mac App Store で &quot;ClipboardxAI&quot; を検索します。</li><li><strong>Get</strong> をクリックしてアプリをダウンロードします。</li><li>アプリは自動的にインストールされます。<strong>Applications</strong> または <strong>Launchpad</strong> から起動してください。</li></ol><h3 id="github-releases" tabindex="-1">GitHub Releases <a class="header-anchor" href="#github-releases" aria-label="Permalink to &quot;GitHub Releases&quot;">​</a></h3><ol><li>Releases ページから最新の <code>.dmg</code> をダウンロードします。</li><li>ダウンロードした <code>.dmg</code> をダブルクリックして開きます。</li><li><code>ClipboardxAI.app</code> アイコンを <strong>Applications</strong> フォルダーにドラッグします。</li><li>マウントされたイメージを取り出し、<strong>Applications</strong> からアプリを開きます。</li></ol><p>macOS がアプリの起動をブロックする場合（Gatekeeper）、<strong>システム設定 → プライバシーとセキュリティ</strong> を開き <strong>このまま開く</strong> をクリックするか、アプリを右クリックして <strong>開く</strong> を選択してください。</p><h2 id="初回起動" tabindex="-1">初回起動 <a class="header-anchor" href="#初回起動" aria-label="Permalink to &quot;初回起動&quot;">​</a></h2><p>初回起動時に、ClipboardxAI は短いセットアップを案内します。</p><ul><li><strong>メニューバー項目を有効にする</strong> — アプリをメニューバーに常駐させます。</li><li><strong>必要な権限を付与する</strong> — バックグラウンドでクリップボードを監視するために必要です（<a href="/ja/guide/permissions.html">権限</a>を参照）。</li><li><em>(オプション)</em> AI アクションが必要な場合は、<strong>設定 → AI</strong> でクラウド AI プロバイダーに接続します。</li></ul><p>求められたタイミングで権限を付与してください。権限はいつでも <strong>システム設定 → プライバシーとセキュリティ</strong> で変更できます。</p><h2 id="アップデート" tabindex="-1">アップデート <a class="header-anchor" href="#アップデート" aria-label="Permalink to &quot;アップデート&quot;">​</a></h2><ul><li><strong>Mac App Store 版</strong>: App Store によって自動的に更新されます。</li><li><strong>GitHub Releases 版</strong>: 新しいリリースをダウンロードし、<code>Applications</code> 内のアプリを置き換えてください。</li></ul><h2 id="アンインストール" tabindex="-1">アンインストール <a class="header-anchor" href="#アンインストール" aria-label="Permalink to &quot;アンインストール&quot;">​</a></h2><p>ClipboardxAI を削除するには：</p><ol><li>アプリを終了します。</li><li><code>ClipboardxAI.app</code> を <code>Applications</code> からゴミ箱にドラッグします。</li><li>（オプション）ローカルデータを削除します：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Containers/com.w3cub.clipboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Application</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Scripts/com.w3cub.clipboard</span></span></code></pre></div><h2 id="システム要件" tabindex="-1">システム要件 <a class="header-anchor" href="#システム要件" aria-label="Permalink to &quot;システム要件&quot;">​</a></h2><ul><li><strong>macOS</strong>: Sonoma（14）以降</li><li><strong>CPU</strong>: Apple Silicon（M シリーズ）または Intel（64 ビット）</li><li><strong>メモリ</strong>: 最小 4 GB、推奨 8 GB</li><li><strong>ストレージ</strong>: 約 50 MB</li></ul><h2 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to &quot;トラブルシューティング&quot;">​</a></h2><p>インストール中に問題が発生した場合：</p><ul><li><strong>macOS がアプリをブロックする</strong>: <strong>システム設定 → プライバシーとセキュリティ</strong> を開き <strong>このまま開く</strong> をクリックします。</li><li><strong>公証（Notarization）の警告</strong>: Mac App Store から署名・公証済みのビルドをダウンロードしてください。</li></ul><p>さらに詳しいヘルプについては、<a href="/ja/guide/troubleshooting.html">トラブルシューティングガイド</a>を参照してください。</p>`,30)])])}const u=i(o,[["render",l]]);export{g as __pageData,u as default};
